const items = $input.all();

for (const item of items) {
  if (!item.binary?.Academic_Paper) {
    throw new Error('Academic_Paper binary file not found');
  }

  item.binary.Academic_Paper.fileExtension = 'zip';
  item.binary.Academic_Paper.mimeType = 'application/zip';
  item.binary.Academic_Paper.fileName = 'paper.zip';
}

return items;

const item = $input.first();

async function binaryToText(binaryProperty) {
  const buffer = await this.helpers.getBinaryDataBuffer(
    0,
    binaryProperty
  );

  return buffer.toString('utf8');
}

const documentXml = await binaryToText.call(this, 'file_4');
const stylesXml = await binaryToText.call(this, 'file_6');

return [{
  json: {
    documentXml,
    stylesXml,
    sourceFile: $('On form submission').first().json['Academic Paper']?.[0]?.filename
  }
}];

const documentXml = $json.documentXml;
const stylesXml = $json.stylesXml;


// ==================================================
// HELPERS
// ==================================================

function decodeXml(text = '') {
  return text
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}


function twipsToCm(twips) {
  if (twips === null || twips === undefined) {
    return null;
  }

  return Number(
    ((Number(twips) / 1440) * 2.54).toFixed(2)
  );
}


// ==================================================
// DOCUMENT DEFAULTS
// ==================================================

// Word stores font size in half-points.
// Example:
// 22 = 11 pt
// 24 = 12 pt

const defaultSizeRaw =
  stylesXml.match(
    /<w:docDefaults>[\s\S]*?<w:sz w:val="(\d+)"/
  )?.[1];


const defaultFontSize =
  defaultSizeRaw
    ? Number(defaultSizeRaw) / 2
    : null;


const defaultFontMatch =
  stylesXml.match(
    /<w:docDefaults>[\s\S]*?<w:rFonts[^>]*w:ascii="([^"]+)"/
  );


const defaultFontFamily =
  defaultFontMatch?.[1] ?? null;


// ==================================================
// PAGE MARGINS
// ==================================================

// Word stores page margins in twips.
// 1440 twips = 1 inch.
// Convert them to centimetres.

const pgMarMatch =
  documentXml.match(
    /<w:pgMar\b([^>]*)\/?>/
  );


let margins = null;


if (pgMarMatch) {

  const marginAttributes =
    pgMarMatch[1];


  const getMarginValue = name => {

    const match =
      marginAttributes.match(
        new RegExp(`w:${name}="(\\d+)"`)
      );

    return match
      ? Number(match[1])
      : null;
  };


  margins = {

    top:
      twipsToCm(
        getMarginValue('top')
      ),

    right:
      twipsToCm(
        getMarginValue('right')
      ),

    bottom:
      twipsToCm(
        getMarginValue('bottom')
      ),

    left:
      twipsToCm(
        getMarginValue('left')
      )
  };
}


// ==================================================
// PARAGRAPHS
// ==================================================

const paragraphMatches =
  documentXml.match(
    /<w:p(?:\s[^>]*)?>[\s\S]*?<\/w:p>/g
  ) || [];


const paragraphs =
  paragraphMatches

    .map((p, index) => {


      // ==============================================
      // PARAGRAPH STYLE
      // ==============================================

      const style =
        p.match(
          /<w:pStyle w:val="([^"]+)"/
        )?.[1] ?? 'Normal';


      // ==============================================
      // LINE SPACING
      // ==============================================

      const spacingTag =
        p.match(
          /<w:spacing[^>]*>/
        )?.[0] ?? '';


      const lineRaw =
        spacingTag.match(
          /w:line="(\d+)"/
        )?.[1];


      const lineRule =
        spacingTag.match(
          /w:lineRule="([^"]+)"/
        )?.[1] ?? null;


      // Word "auto" spacing:
      //
      // 240 = single
      // 360 = 1.5
      // 480 = double

      let lineSpacing = null;


      if (
        lineRaw &&
        (!lineRule || lineRule === 'auto')
      ) {

        lineSpacing =
          Number(lineRaw) / 240;
      }


      // ==============================================
      // PARAGRAPH INDENTATION
      // ==============================================

      // Block quotations are normally represented
      // using paragraph indentation.
      //
      // Word stores indentation in twips.
      // We preserve both the raw twip value and a
      // centimetre representation.

      const indentationTag =
        p.match(
          /<w:ind\b[^>]*\/?>/
        )?.[0] ?? '';


      const getIndentValue = name => {

        const match =
          indentationTag.match(
            new RegExp(`w:${name}="(-?\\d+)"`)
          );

        return match
          ? Number(match[1])
          : null;
      };


      const leftIndentTwips =
        getIndentValue('left');


      const rightIndentTwips =
        getIndentValue('right');


      const firstLineIndentTwips =
        getIndentValue('firstLine');


      const hangingIndentTwips =
        getIndentValue('hanging');


      const indentation = {

        leftTwips:
          leftIndentTwips,

        rightTwips:
          rightIndentTwips,

        firstLineTwips:
          firstLineIndentTwips,

        hangingTwips:
          hangingIndentTwips,

        leftCm:
          twipsToCm(
            leftIndentTwips
          ),

        rightCm:
          twipsToCm(
            rightIndentTwips
          ),

        firstLineCm:
          twipsToCm(
            firstLineIndentTwips
          ),

        hangingCm:
          twipsToCm(
            hangingIndentTwips
          )
      };


      // ==============================================
      // FIGURE / IMAGE DETECTION
      // ==============================================

      // Modern DOCX images normally use <w:drawing>.
      // Older Word formats can use <w:pict>.

      const drawingCount =
        (p.match(/<w:drawing[\s>]/g) || []).length +
        (p.match(/<w:pict[\s>]/g) || []).length;


      const hasFigure =
        drawingCount > 0;


      // ==============================================
      // RUNS
      // ==============================================

      const runMatches =
        p.match(
          /<w:r(?:\s[^>]*)?>[\s\S]*?<\/w:r>/g
        ) || [];


      const runs =
        runMatches.map(run => {


          // ------------------------------------------
          // TEXT
          // ------------------------------------------

          const textParts = [
            ...run.matchAll(
              /<w:t(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g
            )
          ];


          const text =
            textParts
              .map(match =>
                decodeXml(match[1])
              )
              .join('');


          // ------------------------------------------
          // FONT SIZE
          // ------------------------------------------

          const sizeRaw =
            run.match(
              /<w:sz w:val="(\d+)"/
            )?.[1];


          const fontSize =
            sizeRaw
              ? Number(sizeRaw) / 2
              : null;


          // ------------------------------------------
          // FONT FAMILY
          // ------------------------------------------

          const fontsTag =
            run.match(
              /<w:rFonts[^>]*>/
            )?.[0] ?? '';


          const fontFamily =
            fontsTag.match(
              /w:ascii="([^"]+)"/
            )?.[1] ?? null;


          // ------------------------------------------
          // BOLD / ITALIC
          // ------------------------------------------

          const bold =
            /<w:b(?:\/>|>)/.test(run);


          const italic =
            /<w:i(?:\/>|>)/.test(run);


          return {
            text,
            fontSize,
            fontFamily,
            bold,
            italic
          };
        });


      // ==============================================
      // COMPLETE PARAGRAPH TEXT
      // ==============================================

      const text =
        runs
          .map(run => run.text)
          .join('');


      // ==============================================
      // RETURN NORMALIZED PARAGRAPH
      // ==============================================

      return {

        index,

        text,

        style,

        lineSpacing,

        indentation,

        hasFigure,

        drawingCount,

        runs
      };
    })


    // ================================================
    // FILTER
    // ================================================

    // Keep:
    //
    // 1. Normal text paragraphs
    // 2. Image-only paragraphs
    //
    // We deliberately preserve image-only paragraphs
    // because they are required for figure validation.

    .filter(
      paragraph =>
        paragraph.text.trim().length > 0 ||
        paragraph.hasFigure
    );


// ==================================================
// FULL TEXT REPRESENTATION
// ==================================================

// fullText contains textual content only.
// Image-only paragraphs are excluded from this
// representation but remain available in paragraphs.

const fullText =
  paragraphs

    .filter(
      paragraph =>
        paragraph.text.trim().length > 0
    )

    .map(
      paragraph =>
        paragraph.text
    )

    .join('\n');


// ==================================================
// DOCUMENT STATS
// ==================================================

const figureCount =
  paragraphs.reduce(
    (total, paragraph) =>
      total + paragraph.drawingCount,
    0
  );


// ==================================================
// RETURN
// ==================================================

return [{
  json: {

    sourceFile:
      $json.sourceFile,


    defaults: {

      fontSize:
        defaultFontSize,

      fontFamily:
        defaultFontFamily
    },


    layout: {

      margins
    },


    stats: {

      paragraphCount:
        paragraphs.length,

      characterCount:
        fullText.length,

      figureCount
    },


    paragraphs,


    fullText
  }
}];

const data = $input.first().json;

const paragraphs = data.paragraphs.map(p => {

  const resolvedRuns = p.runs.map(run => {

    // Run-specific formatting overrides document defaults.
    // If the run doesn't specify something explicitly,
    // inherit the document default.

    return {
      ...run,

      effectiveFontSize:
        run.fontSize ?? data.defaults.fontSize,

      effectiveFontFamily:
        run.fontFamily ?? data.defaults.fontFamily
    };
  });

  // Only consider runs containing actual visible text
  const textRuns = resolvedRuns.filter(
    r => r.text && r.text.trim().length > 0
  );

  const fontSizes = [
    ...new Set(
      textRuns
        .map(r => r.effectiveFontSize)
        .filter(v => v !== null)
    )
  ];

  const fontFamilies = [
    ...new Set(
      textRuns
        .map(r => r.effectiveFontFamily)
        .filter(Boolean)
    )
  ];

  return {
    ...p,
    runs: resolvedRuns,

    effectiveFormatting: {
      fontSizes,
      fontFamilies,
      lineSpacing: p.lineSpacing
    }
  };
});

return [{
  json: {
    ...data,
    paragraphs
  }
}];

const data = $input.first().json;
const issues = [];


// --------------------------------------------------
// LOAD FORMATTING POLICIES
// --------------------------------------------------

const policies = data.policyPack?.policies || [];

const fontPolicy =
  policies.find(p => p.policy_id === 'POL-008');

const sizePolicy =
  policies.find(p => p.policy_id === 'POL-009');

const spacingPolicy =
  policies.find(p => p.policy_id === 'POL-010');

if (!fontPolicy || !sizePolicy || !spacingPolicy) {
  throw new Error('Required formatting policies are missing from policyPack.');
}

const REQUIRED_FONT = fontPolicy.expected;
const REQUIRED_SIZE = sizePolicy.expected;
const REQUIRED_LINE_SPACING = spacingPolicy.expected;


// --------------------------------------------------
// DETERMINE BODY BOUNDARIES
// --------------------------------------------------

// For V1, body formatting starts after the Abstract heading
// and ends before References.
//
// This prevents title-page text and headings from being
// incorrectly judged as normal body text.

const paragraphs = data.paragraphs || [];

const abstractIndex = paragraphs.findIndex(
  p => (p.text || '').trim().toLowerCase() === 'abstract'
);

const referencesIndex = paragraphs.findIndex(
  p => (p.text || '').trim().toLowerCase() === 'references'
);


// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function isHeading(paragraph) {
  return /^Heading\s?\d$/i.test(paragraph.style || '');
}

function isBodyParagraph(paragraph) {

  if (!paragraph.text?.trim()) {
    return false;
  }

  // Don't validate headings as body typography.
  if (isHeading(paragraph)) {
    return false;
  }

  // Exclude everything before/including Abstract heading.
  if (
    abstractIndex !== -1 &&
    paragraph.index <= paragraphs[abstractIndex].index
  ) {
    return false;
  }

  // Exclude References and everything after it.
  if (
    referencesIndex !== -1 &&
    paragraph.index >= paragraphs[referencesIndex].index
  ) {
    return false;
  }

  return true;
}


// --------------------------------------------------
// VALIDATE BODY FORMATTING
// --------------------------------------------------

for (const paragraph of paragraphs) {

  if (!isBodyParagraph(paragraph)) {
    continue;
  }


  // ------------------------------------------------
  // FONT FAMILY + SIZE
  // ------------------------------------------------

  for (const run of paragraph.runs || []) {

    if (!run.text?.trim()) {
      continue;
    }


    // POL-008 — FONT FAMILY

    if (
      run.effectiveFontFamily &&
      run.effectiveFontFamily !== REQUIRED_FONT
    ) {
      issues.push({
        policy_id: fontPolicy.policy_id,
        code: 'FONT_FAMILY',
        severity: 'ERROR',
        paragraph_index: paragraph.index,
        evidence: run.text.substring(0, 160),
        expected: REQUIRED_FONT,
        detected: run.effectiveFontFamily
      });
    }


    // POL-009 — FONT SIZE

    if (
      run.effectiveFontSize !== null &&
      run.effectiveFontSize !== undefined &&
      run.effectiveFontSize !== REQUIRED_SIZE
    ) {
      issues.push({
        policy_id: sizePolicy.policy_id,
        code: 'FONT_SIZE',
        severity: 'ERROR',
        paragraph_index: paragraph.index,
        evidence: run.text.substring(0, 160),
        expected: REQUIRED_SIZE,
        detected: run.effectiveFontSize
      });
    }
  }


  // ------------------------------------------------
  // POL-010 — LINE SPACING
  // ------------------------------------------------

  if (
    paragraph.lineSpacing !== null &&
    paragraph.lineSpacing !== undefined &&
    Math.abs(
      paragraph.lineSpacing - REQUIRED_LINE_SPACING
    ) > 0.01
  ) {
    issues.push({
      policy_id: spacingPolicy.policy_id,
      code: 'LINE_SPACING',
      severity: 'ERROR',
      paragraph_index: paragraph.index,
      evidence: paragraph.text.substring(0, 160),
      expected: REQUIRED_LINE_SPACING,
      detected: paragraph.lineSpacing
    });
  }
}


// --------------------------------------------------
// SUMMARY
// --------------------------------------------------

const counts = {};

for (const issue of issues) {
  counts[issue.code] =
    (counts[issue.code] || 0) + 1;
}


// --------------------------------------------------
// RETURN
// --------------------------------------------------

return [{
  json: {
    ...data,

    validation: {
      ...(data.validation || {}),

      formatting: {
        status: issues.length === 0 ? 'PASS' : 'FAIL',
        issueCount: issues.length,
        counts,
        issues
      }
    }
  }
}];

const data = $input.first().json;

const paragraphs = data.paragraphs || [];
const policies = data.policyPack?.policies || [];

const issues = [];
const checks = [];


// ------------------------------------
// HELPERS
// ------------------------------------

const normalize = text =>
  (text || '').trim().toLowerCase();

const texts = paragraphs.map(p =>
  normalize(p.text)
);

const getPolicy = policyId => {
  const policy = policies.find(
    p => p.policy_id === policyId
  );

  if (!policy) {
    throw new Error(
      `Policy ${policyId} not found in policyPack.`
    );
  }

  return policy;
};


// ------------------------------------
// REQUIRED SECTION DEFINITIONS
// ------------------------------------

const requiredSections = [
  {
    policy_id: 'POL-001',
    code: 'TITLE_PAGE',
    label: 'Title page',

    test: () => {
      const firstFive = paragraphs
        .slice(0, 5)
        .map(p => (p.text || '').trim())
        .filter(Boolean);

      return firstFive.length >= 3;
    }
  },

  {
    policy_id: 'POL-002',
    code: 'ABSTRACT',
    label: 'Abstract',

    test: () =>
      texts.includes('abstract')
  },

  {
    policy_id: 'POL-004',
    code: 'INTRODUCTION',
    label: 'Introduction',

    test: () =>
      texts.includes('introduction')
  },

  {
    policy_id: 'POL-005',
    code: 'CONCLUSION',
    label: 'Conclusion',

    test: () =>
      texts.includes('conclusion')
  },

  {
    policy_id: 'POL-006',
    code: 'REFERENCES_SECTION',
    label: 'References',

    test: () =>
      texts.includes('references')
  },

  {
    policy_id: 'POL-007',
    code: 'DECLARATION',
    label: 'Declaration of Authorship',

    test: () =>
      texts.some(
        text =>
          text.includes(
            'declaration of authorship'
          )
      )
  }
];


// ------------------------------------
// RUN REQUIRED SECTION CHECKS
// ------------------------------------

for (const section of requiredSections) {

  const policy =
    getPolicy(section.policy_id);

  const present =
    section.test();

  checks.push({
    policy_id: policy.policy_id,
    code: section.code,
    present
  });

  if (!present) {

    issues.push({
      policy_id: policy.policy_id,
      code: section.code,
      severity: 'ERROR',

      expected:
        `${section.label} must be present`,

      detected:
        'NOT_FOUND'
    });
  }
}


// ------------------------------------
// POL-003
// ABSTRACT WORD COUNT
// ------------------------------------

const abstractPolicy =
  getPolicy('POL-003');

const abstractIndex =
  paragraphs.findIndex(
    p => normalize(p.text) === 'abstract'
  );

const introductionIndex =
  paragraphs.findIndex(
    p => normalize(p.text) === 'introduction'
  );


let abstractWordCount = null;
let abstractWordCountPass = false;


// Only evaluate word count when we can
// reliably identify Abstract boundaries.

if (
  abstractIndex !== -1 &&
  introductionIndex > abstractIndex
) {

  const abstractText = paragraphs
    .slice(
      abstractIndex + 1,
      introductionIndex
    )
    .map(p => (p.text || '').trim())
    .filter(Boolean)
    .join(' ');


  abstractWordCount =
    abstractText
      .split(/\s+/)
      .filter(Boolean)
      .length;


  abstractWordCountPass =
    abstractWordCount >=
      abstractPolicy.min_words &&
    abstractWordCount <=
      abstractPolicy.max_words;


  if (!abstractWordCountPass) {

    issues.push({
      policy_id:
        abstractPolicy.policy_id,

      code:
        'ABSTRACT_WORD_COUNT',

      severity:
        'ERROR',

      expected:
        `${abstractPolicy.min_words}-${abstractPolicy.max_words} words`,

      detected:
        abstractWordCount
    });
  }
}


// ------------------------------------
// ADD POL-003 CHECK RESULT
// ------------------------------------

checks.push({
  policy_id:
    abstractPolicy.policy_id,

  code:
    'ABSTRACT_WORD_COUNT',

  checked:
    abstractWordCount !== null,

  wordCount:
    abstractWordCount,

  expected: {
    min:
      abstractPolicy.min_words,

    max:
      abstractPolicy.max_words
  },

  pass:
    abstractWordCountPass
});


// ------------------------------------
// RETURN
// ------------------------------------

return [{
  json: {
    ...data,

    validation: {
      ...(data.validation || {}),

      structure: {
        status:
          issues.length === 0
            ? 'PASS'
            : 'FAIL',

        issueCount:
          issues.length,

        checks,
        issues
      }
    }
  }
}];

const data = $input.first().json;
const paragraphs = data.paragraphs || [];
const issues = [];


// ------------------------------------
// FIND REFERENCES / DECLARATION
// ------------------------------------

const referencesIndex = paragraphs.findIndex(
  p => (p.text || '').trim().toLowerCase() === 'references'
);

const declarationIndex = paragraphs.findIndex(
  p =>
    (p.text || '')
      .trim()
      .toLowerCase()
      .includes('declaration of authorship')
);


// ------------------------------------
// REFERENCES SECTION REQUIRED
// ------------------------------------

if (referencesIndex === -1) {
  return [{
    json: {
      ...data,

      validation: {
        ...(data.validation || {}),

        citations: {
          status: 'SKIPPED',
          reason: 'References section not found',
          issueCount: 0,
          issues: []
        }
      }
    }
  }];
}


// ------------------------------------
// SPLIT DOCUMENT
// ------------------------------------

const bodyParagraphs =
  paragraphs.slice(0, referencesIndex);

const referenceParagraphs =
  paragraphs.slice(
    referencesIndex + 1,
    declarationIndex > referencesIndex
      ? declarationIndex
      : paragraphs.length
  );


// ------------------------------------
// EXTRACT CITATIONS
// ------------------------------------

const citationKeys = new Set();

for (const p of bodyParagraphs) {

  const text = p.text || '';


  // --------------------------------
  // PARENTHETICAL CITATIONS
  //
  // (Weber, 2021)
  // (Weber, 2021, p. 42)
  // (Nakamura et al., 2022)
  // --------------------------------

  const parenthetical = [
    ...text.matchAll(
      /\(([A-Z][A-Za-zÀ-ÿ'-]+)(?:\s+et\s+al\.)?,\s*(\d{4})[^)]*\)/g
    )
  ];

  for (const match of parenthetical) {
    citationKeys.add(
      `${match[1].toLowerCase()}|${match[2]}`
    );
  }


  // --------------------------------
  // NARRATIVE CITATIONS
  //
  // Weber (2021)
  // Ruiz and Stein (2021)
  // Ruiz & Stein (2021)
  // Nakamura et al. (2022)
  //
  // Always normalize using
  // FIRST AUTHOR + YEAR.
  // --------------------------------

  const narrative = [
    ...text.matchAll(
      /\b([A-Z][A-Za-zÀ-ÿ'-]+)(?:\s+(?:and|&)\s+[A-Z][A-Za-zÀ-ÿ'-]+|\s+et\s+al\.)?\s*\((\d{4})\)/g
    )
  ];

  for (const match of narrative) {
    citationKeys.add(
      `${match[1].toLowerCase()}|${match[2]}`
    );
  }
}


// ------------------------------------
// EXTRACT REFERENCES
// ------------------------------------

const references = [];

for (const p of referenceParagraphs) {

  const text = (p.text || '').trim();

  if (!text) continue;


  // Examples:
  //
  // Weber, M. (2021).
  // Ruiz, L., & Stein, M. (2021).

  const match =
    text.match(
      /^([A-Z][A-Za-zÀ-ÿ'-]+).*?\((\d{4})\)/
    );

  if (!match) continue;


  references.push({
    surname: match[1],
    year: match[2],

    key:
      `${match[1].toLowerCase()}|${match[2]}`,

    text
  });
}


const referenceKeys =
  new Set(
    references.map(ref => ref.key)
  );


// ------------------------------------
// POL-012
// CITATION → REFERENCE
// ------------------------------------

for (const key of citationKeys) {

  if (!referenceKeys.has(key)) {

    const [surname, year] =
      key.split('|');

    issues.push({
      policy_id: 'POL-012',
      code: 'CITATION_WITHOUT_REFERENCE',
      severity: 'ERROR',

      evidence:
        `${surname} (${year})`,

      expected:
        'Matching References entry',

      detected:
        'NOT_FOUND'
    });
  }
}


// ------------------------------------
// POL-013
// REFERENCE → CITATION
// ------------------------------------

for (const ref of references) {

  if (!citationKeys.has(ref.key)) {

    issues.push({
      policy_id: 'POL-013',
      code: 'UNCITED_REFERENCE',
      severity: 'ERROR',

      evidence:
        ref.text.substring(0, 180),

      expected:
        'At least one in-text citation',

      detected:
        'NOT_FOUND'
    });
  }
}


// ------------------------------------
// POL-014
// ALPHABETICAL REFERENCES
// ------------------------------------

const actualOrder =
  references.map(
    ref => ref.surname.toLowerCase()
  );

const expectedOrder =
  [...actualOrder].sort(
    (a, b) => a.localeCompare(b)
  );

const alphabetical =
  actualOrder.every(
    (surname, index) =>
      surname === expectedOrder[index]
  );


if (!alphabetical) {

  issues.push({
    policy_id: 'POL-014',
    code: 'REFERENCES_NOT_ALPHABETICAL',
    severity: 'ERROR',

    expected: expectedOrder,
    detected: actualOrder
  });
}


// ------------------------------------
// RETURN
// ------------------------------------

return [{
  json: {
    ...data,

    citationAnalysis: {
      citationsDetected:
        [...citationKeys],

      referencesDetected:
        references,

      citationCount:
        citationKeys.size,

      referenceCount:
        references.length
    },

    validation: {
      ...(data.validation || {}),

      citations: {
        status:
          issues.length === 0
            ? 'PASS'
            : 'FAIL',

        issueCount:
