const paragraphs = data.paragraphs || [];
const policies = data.policyPack?.policies || [];


// ==================================================
// POLICY
// ==================================================

const policy = policies.find(
  p => p.policy_id === 'POL-015'
);

if (!policy) {
  throw new Error(
    'POL-015 not found in policyPack.'
  );
}


const minimumWords =
  policy.min_block_quote_words ?? 40;


// ==================================================
// HELPERS
// ==================================================

function countWords(text = '') {

  return text
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;
}


function isIndented(paragraph) {

  const indentation =
    paragraph.indentation || {};

  const left =
    indentation.leftTwips;

  // Any meaningful positive left indentation
  // is treated as structural block-quote evidence.
  //
  // 360 twips ≈ 0.64 cm.
  // This avoids treating tiny formatting noise
  // as a block quotation.

  return (
    left !== null &&
    left !== undefined &&
    left >= 360
  );
}


// ==================================================
// BODY SCOPE
// ==================================================

// We do not want quotation marks appearing inside
// the References or Declaration sections to trigger
// long-quote validation.

const referencesPosition =
  paragraphs.findIndex(
    p =>
      p.text.trim().toLowerCase() ===
      'references'
  );


const bodyParagraphs =
  referencesPosition >= 0
    ? paragraphs.slice(0, referencesPosition)
    : paragraphs;


// ==================================================
// DETECT QUOTED PASSAGES
// ==================================================

// Detect:
// "quoted text"
// “quoted text”
//
// The regex intentionally operates paragraph-by-
// paragraph. A quotation spanning several paragraphs
// becomes ambiguous and should not be silently judged.

const quotePatterns = [

  /"([^"]+)"/g,

  /“([^”]+)”/g
];


const candidates = [];


// ==================================================
// ANALYSE PARAGRAPHS
// ==================================================

for (const paragraph of bodyParagraphs) {

  const text =
    paragraph.text || '';

  if (!text.trim()) {
    continue;
  }


  for (const pattern of quotePatterns) {

    pattern.lastIndex = 0;

    let match;


    while (
      (match = pattern.exec(text)) !== null
    ) {

      const quoteText =
        match[1].trim();


      const wordCount =
        countWords(
          quoteText
        );


      if (
        wordCount < minimumWords
      ) {
        continue;
      }


      const indented =
        isIndented(
          paragraph
        );


      candidates.push({

        paragraphIndex:
          paragraph.index,

        quoteText,

        wordCount,

        indentation:
          paragraph.indentation,

        structurallyIndented:
          indented,

        hasQuotationMarks:
          true
      });
    }
  }
}


// ==================================================
// CLASSIFY CANDIDATES
// ==================================================

const issues = [];

const reviewItems = [];


for (const candidate of candidates) {


  // ------------------------------------------------
  // CLEAR INLINE LONG QUOTATION
  // ------------------------------------------------
  //
  // 40+ words
  // quotation marks
  // no block indentation
  //
  // This is strong evidence that POL-015 has been
  // violated.

  if (
    !candidate.structurallyIndented
  ) {

    issues.push({

      policy_id:
        policy.policy_id,

      code:
        'LONG_QUOTE_NOT_BLOCK_FORMATTED',

      severity:
        'ERROR',

      paragraphIndex:
        candidate.paragraphIndex,

      wordCount:
        candidate.wordCount,

      expected:
        `${minimumWords}+ word direct quotations must use block formatting without quotation marks`,

      detected:
        'Long quotation enclosed in quotation marks without block indentation',

      evidence:
        candidate.quoteText
    });

    continue;
  }


  // ------------------------------------------------
  // INDENTED BUT STILL HAS QUOTATION MARKS
  // ------------------------------------------------
  //
  // Structurally this looks like a block quote,
  // but it still uses quotation marks.
  //
  // We preserve this as a review case instead of
  // pretending the formatting is unquestionably
  // correct.

  reviewItems.push({

    policy_id:
      policy.policy_id,

    code:
      'LONG_QUOTE_REQUIRES_REVIEW',

    severity:
      'REVIEW',

    paragraphIndex:
      candidate.paragraphIndex,

    wordCount:
      candidate.wordCount,

    reason:
      'Long quotation is indented but still contains quotation marks.',

    evidence:
      candidate.quoteText
  });
}


// ==================================================
// DETECT POSSIBLE UNQUOTED BLOCK QUOTES
// ==================================================
//
// An indented paragraph with 40+ words may be a
// correctly formatted block quotation.
//
// But indentation alone cannot prove that the text
// is actually a quotation.
//
// This is exactly the kind of ambiguity we should
// surface instead of forcing a deterministic answer.

for (const paragraph of bodyParagraphs) {

  const text =
    paragraph.text?.trim() || '';


  if (!text) {
    continue;
  }


  const wordCount =
    countWords(
      text
    );


  if (
    wordCount < minimumWords
  ) {
    continue;
  }


  if (
    !isIndented(paragraph)
  ) {
    continue;
  }


  // Avoid duplicating paragraphs already detected
  // through explicit quotation marks.

  const alreadyDetected =
    candidates.some(
      candidate =>
        candidate.paragraphIndex ===
        paragraph.index
    );


  if (alreadyDetected) {
    continue;
  }


  reviewItems.push({

    policy_id:
      policy.policy_id,

    code:
      'POSSIBLE_BLOCK_QUOTE',

    severity:
      'REVIEW',

    paragraphIndex:
      paragraph.index,

    wordCount,

    reason:
      'Paragraph is long and structurally indented. It may be a correctly formatted block quotation and requires semantic confirmation.',

    evidence:
      text
  });
}


// ==================================================
// FINAL STATUS
// ==================================================

let status = 'PASS';


if (issues.length > 0) {

  status = 'FAIL';

} else if (
  reviewItems.length > 0
) {

  status = 'REVIEW_REQUIRED';
}


// ==================================================
// RETURN
// ==================================================

return [{
  json: {
    ...data,

    validation: {
      ...(data.validation || {}),

      longQuotations: {

        policy_id:
          policy.policy_id,

        status,

        minimumWords,

        candidateCount:
          candidates.length,

        candidates,

        issueCount:
          issues.length,

        issues,

        reviewCount:
          reviewItems.length,

        reviewItems
      }
    }
  }
}];

