// Current formatting validator returns an aggregate
// result for these three policies.
//
// If the formatting validator passes, all three
// formatting policies passed.
//
// On failure, we inspect issue.policy_id where
// available to identify the affected rule.
// ==================================================

const formatting =
  validation.formatting || {};


for (const policyId of [
  'POL-008',
  'POL-009',
  'POL-010'
]) {

  const policyIssues =
    (formatting.issues || [])
      .filter(
        issue =>
          issue.policy_id === policyId
      );


  let status =
    'NOT_CHECKED';


  if (
    formatting.status === 'PASS'
  ) {

    status = 'PASS';

  } else if (
    formatting.status === 'FAIL'
  ) {

    status =
      policyIssues.length > 0
        ? 'FAIL'
        : 'PASS';
  }


  results.push({

    policy_id:
      policyId,

    name:
      policyName(policyId),

    category:
      categoryMap[policyId],

    status,

    issues:
      policyIssues
  });
}


// ==================================================
// POL-011
// MARGINS
// ==================================================

const margins =
  validation.margins;


results.push({

  policy_id:
    'POL-011',

  name:
    policyName('POL-011'),

  category:
    categoryMap['POL-011'],

  status:
    margins
      ? normalizeStatus(
          margins.status
        )
      : 'NOT_CHECKED',

  issues:
    margins?.issues || []
});


// ==================================================
// POL-012 → POL-014
// CITATIONS
// ==================================================
//
// Like formatting, the current citation validator
// exposes an aggregate status.
//
// PASS means all three citation policies passed.
//
// On FAIL we use policy_id on individual issues to
// determine which policy failed.
// ==================================================

const citations =
  validation.citations || {};


for (const policyId of [
  'POL-012',
  'POL-013',
  'POL-014'
]) {

  const policyIssues =
    (citations.issues || [])
      .filter(
        issue =>
          issue.policy_id === policyId
      );


  let status =
    'NOT_CHECKED';


  if (
    citations.status === 'PASS'
  ) {

    status = 'PASS';

  } else if (
    citations.status === 'FAIL'
  ) {

    status =
      policyIssues.length > 0
        ? 'FAIL'
        : 'PASS';
  }


  results.push({

    policy_id:
      policyId,

    name:
      policyName(policyId),

    category:
      categoryMap[policyId],

    status,

    issues:
      policyIssues
  });
}


// ==================================================
// POL-015
// LONG QUOTATIONS
// ==================================================

const longQuotations =
  validation.longQuotations;


results.push({

  policy_id:
    'POL-015',

  name:
    policyName('POL-015'),

  category:
    categoryMap['POL-015'],

  status:
    longQuotations
      ? normalizeStatus(
          longQuotations.status
        )
      : 'NOT_CHECKED',

  issues: [
    ...(
      longQuotations?.issues || []
    ),
    ...(
      longQuotations?.reviewItems || []
    )
  ]
});


// ==================================================
// POL-016 / POL-017
// FIGURES
// ==================================================

const figures =
  validation.figures || {};


for (const policyId of [
  'POL-016',
  'POL-017'
]) {

  const key =
    policyId.replace(
      '-',
      '_'
    );


  const result =
    figures.policies?.[key];


  results.push({

    policy_id:
      policyId,

    name:
      policyName(policyId),

    category:
      categoryMap[policyId],

    status:
      result
        ? normalizeStatus(
            result.status
          )
        : 'NOT_CHECKED',

    issues:
      result?.issues || []
  });
}


// ==================================================
// POL-018
// HEADING HIERARCHY
// ==================================================

const headings =
  validation.headings;


results.push({

  policy_id:
    'POL-018',

  name:
    policyName('POL-018'),

  category:
    categoryMap['POL-018'],

  status:
    headings
      ? normalizeStatus(
          headings.status
        )
      : 'NOT_CHECKED',

  issues:
    headings?.issues || []
});


// ==================================================
// SORT
// ==================================================

results.sort(
  (a, b) =>
    a.policy_id.localeCompare(
      b.policy_id
    )
);


// ==================================================
// COUNTS
// ==================================================

const counts = {

  total:
    results.length,

  passed:
    results.filter(
      r => r.status === 'PASS'
    ).length,

  failed:
    results.filter(
      r => r.status === 'FAIL'
    ).length,

  reviewRequired:
    results.filter(
      r =>
        r.status ===
        'REVIEW_REQUIRED'
    ).length,

  notChecked:
    results.filter(
      r =>
        r.status ===
        'NOT_CHECKED'
    ).length
};


// ==================================================
// OVERALL STATUS
// ==================================================

let overallStatus =
  'PASS';


if (
  counts.failed > 0
) {

  overallStatus =
    'FAIL';

} else if (
  counts.reviewRequired > 0 ||
  counts.notChecked > 0
) {

  overallStatus =
    'REVIEW_REQUIRED';
}


// ==================================================
// FLATTEN ISSUES
// ==================================================

const issues = [];


for (const result of results) {

  for (
    const issue of result.issues
  ) {

    issues.push({

      policy_id:
        result.policy_id,

      policy:
        result.name,

      category:
        result.category,

      status:
        result.status,

      severity:
        issue.severity ||
        (
          result.status === 'FAIL'
            ? 'ERROR'
            : 'REVIEW'
        ),

      code:
        issue.code || null,

      paragraphIndex:
        issue.paragraphIndex ??
        issue.figureParagraphIndex ??
        null,

      expected:
        issue.expected ?? null,

      detected:
        issue.detected ?? null,

      reason:
        issue.reason ?? null,

      evidence:
        shortenEvidence(
          issue.evidence
        )
    });
  }
}


// ==================================================
// SUMMARY
// ==================================================

let summary;


if (
  overallStatus === 'PASS'
) {

  summary =
    `PASS — ${counts.passed}/${counts.total} university policies passed. No compliance issues were detected.`;

} else if (
  overallStatus === 'FAIL'
) {

  summary =
    `FAIL — ${counts.failed} policy check(s) failed. ${counts.passed}/${counts.total} policies passed.`;

} else {

  summary =
    `REVIEW REQUIRED — ${counts.reviewRequired} policy check(s) require review and ${counts.notChecked} were not checked automatically.`;
}


// ==================================================
// FINAL REPORT
// ==================================================

return [{
  json: {

    system:
      'PAPERGUARD',

    sourceFile:
      data.sourceFile || null,

    policyPack: {

      id:
        data.policyPack?.id ||
        null,

      institution:
        data.policyPack
          ?.institution ||
        null,

      version:
        data.policyPack
          ?.version ||
        null
    },

    overallStatus,

    summary,

    counts,

    issues,

    policies:
      results.map(
        result => ({

          policy_id:
            result.policy_id,

          name:
            result.name,

          category:
            result.category,

          status:
            result.status,

          issueCount:
            result.issues.length
        })
      ),

    documentStats:
      data.stats || null,

    generatedAt:
      new Date().toISOString()
  }
}];

const report = $input.first().json;

const status = report.overallStatus;
const counts = report.counts || {};
const issues = report.issues || [];


// ============================================
// STATUS DISPLAY
// ============================================

let statusTitle;
let statusMessage;

if (status === 'PASS') {

  statusTitle = '✓ PAPER PASSED';

  statusMessage =
    'Your paper meets all automatically checked requirements of the configured university policy.';

} else if (status === 'FAIL') {

  statusTitle = '✕ CHANGES REQUIRED';

  statusMessage =
    'Your paper does not currently meet all requirements of the configured university policy.';

} else {

  statusTitle = '⚠ REVIEW REQUIRED';

  statusMessage =
    'Some requirements could not be evaluated conclusively and require review.';
}


// ============================================
// CATEGORY SUMMARY
// ============================================

const categoryNames = {
  STRUCTURE: 'Structure',
  FORMATTING: 'Formatting',
  LAYOUT: 'Layout',
  CITATIONS: 'Citations & References',
  QUOTATIONS: 'Quotations',
  FIGURES: 'Figures'
};

const categories = {};

for (const policy of report.policies || []) {

  const category =
    policy.category || 'OTHER';

  if (!categories[category]) {

    categories[category] = {
      total: 0,
      passed: 0,
      failed: 0,
      review: 0
    };
  }

  categories[category].total++;

  if (policy.status === 'PASS') {
    categories[category].passed++;
  }

  if (policy.status === 'FAIL') {
    categories[category].failed++;
  }

  if (policy.status === 'REVIEW_REQUIRED') {
    categories[category].review++;
  }
}


const categorySummary =
  Object.entries(categories)
    .map(([key, value]) => {

      let status = 'PASS';

      if (value.failed > 0) {
        status = 'FAIL';
      } else if (value.review > 0) {
        status = 'REVIEW_REQUIRED';
      }

      return {
        category: key,
        label: categoryNames[key] || key,
        status,
        passed: value.passed,
        total: value.total
      };
    });


// ============================================
// HUMAN-READABLE ISSUES
// ============================================

const issueSummary =
  issues.map((issue, index) => {

    let message =
      issue.policy;

    if (issue.evidence) {
      message += ` — ${issue.evidence}`;
    }

    return {
      number: index + 1,
      policy_id: issue.policy_id,
      title: issue.policy,
      severity: issue.severity,
      message,
      expected: issue.expected,
      detected: issue.detected,
      reason: issue.reason
    };
  });


// ============================================
// OUTPUT FOR FORM ENDING
// ============================================

return [{
  json: {

    status,

    statusTitle,

    statusMessage,

    file:
      report.sourceFile,

    score:
      `${counts.passed}/${counts.total}`,

    passed:
      counts.passed,

    total:
      counts.total,

    failed:
      counts.failed,

    reviewRequired:
      counts.reviewRequired,

    issueCount:
      issues.length,

    categories:
      categorySummary,

    issues:
      issueSummary,

    institution:
      report.policyPack?.institution,

    policyVersion:
      report.policyPack?.version
  }
}];
